    descriptionAdvanced: {
      de: "Das Reservat Plaiul Fagului wurde 1991 auf der Grundlage eines ehemaligen Jagdreviers gegründet und umfasst etwa 5.642 Hektar im Bezirk Ungheni. Der Name bedeutet 'Land der Buchen' und verweist auf die hier vorkommenden Buchenwälder, die an der östlichen Grenze ihres natürlichen Verbreitungsgebiets in Europa liegen. Das Gelände ist stark fragmentiert, mit steilen Hängen und zahlreichen Quellen, die den Fluss Bîc speisen. Neben den Buchen sind Eichen, Eschen und Wildkirschen prägend für das Waldbild. Die Fauna umfasst seltene Arten wie den Rothirsch, der hier erfolgreich akklimatisiert wurde, sowie Wildschweine und Rehe. Das Reservat spielt eine entscheidende Rolle beim Erhalt der genetischen Vielfalt mitteleuropäischer Laubwälder innerhalb des moldauischen Territoriums.",
      hu: "A Plaiul Fagului rezervátumot 1991-ben hozták létre egy korábbi vadászterület alapjain, és mintegy 5642 hektárt foglal el az Ungheni járásban. Neve 'Bükk-vidéket' jelent, utalva az itt található bükkerdőkre, amelyek európai elterjedésük keleti határát képviselik. A terep erősen tagolt, meredek lejtőkkel és számos forrással, amelyek a Bîc folyót táplálják. A bükk mellett a tölgy, a kőris és a vadcseresznye is meghatározó az erdőképben. Az állatvilág olyan ritka fajokat foglal magában, mint a gímszarvas, amelyet itt sikeresen honosítottak, valamint a vaddisznó és az őz. A rezervátum döntő szerepet játszik a közép-európai lombhullató erdők genetikai sokféleségének megőrzésében Moldova területén belül.",
      ro: "Rezervația Plaiul Fagului a fost constituită în anul 1991 pe baza unei foste gospodării cinegetice, acoperind o suprafață de circa 5.642 de hectare în raionul Ungheni. Denumirea sa semnifică 'Ținutul Fagului', reflectând prezența pădurilor de fag care se află aici la limita estică a arealului lor natural european. Relieful este foarte fragmentat, cu pante abrupte și numeroase izvoare care alimentează cursul superior al râului Bîc. Pe lângă fag, compoziția forestieră include stejarul, frasinul și cireșul sălbatic. Fauna este diversă, cuprinzând specii precum cerbul nobil, care a fost aclimatizat cu succes, mistrețul și căpriorul. Rezervația are un rol strategic în conservarea diversității genetice a pădurilor de foioase central-europene pe teritoriul Republicii Moldova.",
      en: "The Plaiul Fagului Reserve was established in 1991 from a former hunting ground and covers approximately 5,642 hectares in the Ungheni District. Its name means 'Land of the Beech', referring to the local beech forests that mark the easternmost limit of their natural distribution in Europe. The terrain is highly fragmented, characterized by steep slopes and numerous springs that feed the Bîc River. In addition to beech, the forest composition includes oak, ash, and wild cherry trees. The fauna features rare species such as the red deer, which has been successfully acclimated here, along with wild boars and roe deer. The reserve plays a crucial role in preserving the genetic diversity of Central European deciduous forests within Moldovan territory.",
      es: "La reserva Plaiul Fagului protege raros bosques de hayas en el límite oriental de su área de distribución. Se encuentra en la parte noroeste de la región de Codru, sobre más de 5.600 hectáreas.",
      pt: "A reserva Plaiul Fagului protege raras florestas de faias no limite oriental da sua área de distribuição. Situa-se na parte noroeste da região de Codru, com mais de 5.600 hectares.",
      fr: "La réserve de Plaiul Fagului protège des forêts de hêtres rares à la limite orientale de leur aire de répartition. Elle est située dans la partie nord-ouest de la région de Codru sur plus de 5 600 hectares.",
    },
    factsAdvanced: {
      de: ["Gründungsjahr: 1991", "Fläche: 5.642 Hektar", "Östlichste Grenze der Buchenwälder in Europa", "Beherbergt über 900 Pflanzenarten", "Vorkommen des Rothirsches (Cervus elaphus)", "Schutzgebiet im Bezirk Ungheni (nahe Rădenii Vechi)"],
      hu: ["Alapítás éve: 1991", "Terület: 5642 hektár", "A bükkerdők legkeletibb határa Európában", "Több mint 900 növényfaj található itt", "Gímszarvas (Cervus elaphus) előfordulása", "Az Ungheni járásban található (Rădenii Vechi közelében)"],
      ro: ["Anul înființării: 1991", "Suprafața: 5.642 hectare", "Limita estică a pădurilor de fag din Europa", "Adăpostește peste 900 de specii de plante", "Prezența cerbului nobil (Cervus elaphus)", "Situată în raionul Ungheni (lângă Rădenii Vechi)"],
      en: ["Year of establishment: 1991", "Area: 5,642 hectares", "Easternmost limit of beech forests in Europe", "Home to over 900 plant species", "Presence of red deer (Cervus elaphus)", "Located in Ungheni District (near Rădenii Vechi)"],
      es: ["Fundada el 12 de mayo de 1992", "Superficie de unas 5642 hectáreas", "Las hayas representan el 5% del bosque", "Más de 900 especies de plantas diferentes"],
      pt: ["Fundada em 12 de maio de 1992", "Área de cerca de 5642 hectares", "As faias representam 5% da floresta", "Mais de 900 espécies de plantas diferentes"],
      fr: ["Créée le 12 mai 1992", "Superficie d'environ 5 642 hectares", "Les hêtres représentent 5 % de la forêt", "Plus de 900 espèces végétales différentes"],
    },
