      hu: ["1988-ban alapították", "Vízparti ökoszisztémákra fókuszál", "Gazdag halfauna", "Dnyeszteren túli területen fekszik"],
      ro: ["Înființată în 1988", "Focus pe ecosisteme acvatice", "Ihtiofaună bogată", "Situată în regiunea transnistreană"],
