      es: ["Fundada en el año 1988", "Enfoque en ecosistemas acuáticos", "Rica fauna de peces", "Se encuentra en Transnistria"],
      pt: ["Fundada no ano de 1988", "Foco em ecossistemas aquáticos", "Rica fauna de peixes", "Localizada na Transnístria"],
