    imageHint: "Botanical Garden Chisinau blooming flowers",
    image: "/poi-images/moldova-chisinau-botanical-garden-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Botanische Garten von Chișinău wurde 1950 gegründet, befindet sich jedoch seit 1973 an seinem heutigen Standort im Stadtteil Botanica. Auf einer Fläche von 104 Hektar beherbergt er über 10.000 Pflanzenarten, Unterarten und Sorten aus aller Welt. Das Gelände ist kunstvoll gestaltet, mit künstlichen Teichen, Themengärten wie dem Rosarium und dem Syringarium sowie weitläufigen Alleen. Ein modernes Gewächshauskomplex ermöglicht die Kultivierung tropischer und subtropischer Pflanzen. Der Garten dient nicht nur der wissenschaftlichen Forschung und dem Erhalt gefährdeter Arten, sondern ist auch ein beliebtes Naherholungsgebiet für die Stadtbevölkerung. Er ist ein bedeutendes Zentrum für botanische Bildung und trägt zur ökologischen Aufklärung in der Republik Moldau bei.",
      hu: "A Chișinăui Botanikus Kertet 1950-ben alapították, de 1973 óta található jelenlegi helyén, a Botanica negyedben. A 104 hektáros területen több mint 10 000 növényfaj, alfaj és fajta kapott helyet a világ minden tájáról. A kert művészien kialakított, mesterséges tavakkal, tematikus kertekkel, például rózsakerttel és orgonakerttel, valamint tágas sétányokkal rendelkezik. Egy modern üvegház-komplexum teszi lehetővé a trópusi és szubtrópusi növények termesztését. A kert nemcsak a tudományos kutatást és a veszélyeztetett fajok megőrzését szolgálja, hanem a városi lakosság kedvelt pihenőhelye is. Fontos központja a botanikai oktatásnak, és jelentősen hozzájárul a környezettudatosság növeléséhez Moldovában.",
      ro: "Grădina Botanică din Chișinău a fost fondată în anul 1950, însă din 1973 se află pe amplasamentul actual din sectorul Botanica al capitalei. Pe o suprafață de 104 hectare, instituția găzduiește peste 10.000 de specii, subspecii și soiuri de plante provenite din întreaga lume. Teritoriul este amenajat peisagistic, incluzând lacuri artificiale, sectoare tematice precum Rozariul și Siringariul, și alei largi. Un complex modern de sere permite cultivarea plantelor tropicale și subtropicale. Grădina nu servește doar cercetării științifice și conservării speciilor periclitate, ci este și un spațiu de recreere major pentru locuitorii orașului. Reprezintă un centru important pentru educația botanică și contribuie activ la conștientizarea ecologică în Republica Moldova.",
      en: "The Chișinău Botanical Garden was founded in 1950, but it has been at its current location in the Botanica district since 1973. Spanning 104 hectares, it houses over 10,000 species, subspecies, and varieties of plants from all over the world. The grounds are artistically landscaped, featuring artificial ponds, themed sections like the Rosarium and Syringarium, and broad avenues. A modern greenhouse complex allows for the cultivation of tropical and subtropical plants. The garden serves not only scientific research and the conservation of endangered species but is also a popular recreational area for the city's residents. It is a significant center for botanical education and contributes to ecological awareness in the Republic of Moldova.",
      es: "El Jardín Botánico de Chisináu abarca más de 100 hectáreas y presenta más de 10.000 especies de plantas. Es un centro dedicado a la investigación científica y al esparcimiento.",
      pt: "O Jardim Botânico de Chișinău abrange mais de 100 hectares e apresenta mais de 10.000 espécies de plantas. É um centro dedicado à pesquisa científica e ao lazer.",
      fr: "Le jardin botanique de Chișinău couvre plus de 100 hectares et présente plus de 10 000 espèces de plantes. C'est un centre de recherche scientifique et de loisirs.",
    },
