    image: "/poi-images/moldova-chisinau-zoo-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Zoo von Chișinău wurde am 9. Mai 1978 eröffnet und befindet sich am südlichen Stadtrand, direkt gegenüber dem Botanischen Garten. Er erstreckt sich über eine Fläche von etwa 25 Hektar und beherbergt eine Sammlung von über 700 Tieren aus rund 130 Arten. Die Anlage umfasst Gehege für Großkatzen, Bären, Huftiere sowie ein Reptilienhaus und ein Vogelhaus. Ein zentraler See bietet Lebensraum für Schwäne und Pelikane. Der Zoo beteiligt sich an internationalen Programmen zur Zucht gefährdeter Arten, wie beispielsweise dem Schneeleoparden. In den letzten Jahren wurden viele Anlagen modernisiert, um den Tieren artgerechtere Bedingungen zu bieten und das Erlebnis für Besucher, insbesondere Familien mit Kindern, zu verbessern.",
      hu: "A Chișinăui Állatkert 1978. május 9-én nyílt meg a város déli szélén, közvetlenül a Botanikus Kerttel szemben. Mintegy 25 hektáros területen helyezkedik el, és több mint 700 állatnak ad otthont, amelyek körülbelül 130 fajt képviselnek. A létesítményben nagymacskák, medvék, patások kifutói, valamint hüllőház és madárház található. Egy központi tó biztosít élőhelyet a hattyúknak és pelikánoknak. Az állatkert részt vesz a veszélyeztetett fajok, például a hópárduc tenyésztésére irányuló nemzetközi programokban. Az elmúlt években számos kifutót korszerűsítettek, hogy az állatoknak természetközelibb körülményeket biztosítsanak, és javítsák a látogatói élményt, különösen a kisgyermekes családok számára.",
      ro: "Grădina Zoologică din Chișinău a fost inaugurată la 9 mai 1978 și este situată la periferia sudică a capitalei, vis-a-vis de Grădina Botanică. Aceasta se întinde pe o suprafață de aproximativ 25 de hectare și adăpostește o colecție de peste 700 de animale din circa 130 de specii. Complexul include voliere pentru feline mari, urși, copitate, precum și un terariu și un sector ornitologic. Un lac central oferă un mediu propice pentru lebede și pelicani. Grădina Zoologică participă în programe internaționale de reproducere a speciilor periclitate, cum ar fi leopardul zăpezilor. În ultimii ani, multe dintre spații au fost modernizate pentru a oferi condiții mai bune animalelor și pentru a îmbunătăți experiența vizitatorilor, fiind o destinație preferată pentru familii.",
      en: "The Chișinău Zoo was inaugurated on May 9, 1978, and is located on the southern outskirts of the capital, directly across from the Botanical Garden. It spans an area of approximately 25 hectares and houses a collection of over 700 animals from about 130 species. The facility includes enclosures for big cats, bears, ungulates, as well as a terrarium and a bird section. A central lake provides a habitat for swans and pelicans. The zoo participates in international breeding programs for endangered species, such as the snow leopard. In recent years, many of the enclosures have been modernized to provide more natural conditions for the animals and to enhance the experience for visitors, especially families with children.",
      es: "El Zoológico de Chisináu alberga más de 1000 animales de todo el mundo en 25 hectáreas. Es un destino familiar popular con una gran colección de especies raras de aves y depredadores.",
      pt: "O Jardim Zoológico de Chișinău abriga mais de 1000 animais de todo o mundo em 25 hectares. É um destino familiar popular com uma grande coleção de espécies raras de aves e predadores.",
      fr: "Le zoo de Chișinău abrite plus de 1 000 animaux du monde entier sur 25 hectares. C'est une destination familiale prisée, dotée d'une grande collection d'oiseaux rares et de prédateurs.",
    },
