    image: "/poi-images/moldova-taul-park-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Taul-Park im Bezirk Dondușeni ist mit 46 Hektar die größte Parkanlage der Republik Moldau. Er wurde zwischen 1901 und 1912 rund um das Herrenhaus des Bankiers Andrei Pommer angelegt. Die Gestaltung stammt vom Landschaftsarchitekten Ippolit Padalko, der eine harmonische Verbindung aus einheimischen und exotischen Pflanzen schuf. Der Park ist in einen oberen Teil mit dem Herrenhaus und einen unteren Teil mit Waldcharakter unterteilt. Es gibt über 150 Baum- und Straucharten, von denen viele aus verschiedenen Teilen der Welt importiert wurden. Das Herrenhaus selbst ist ein Architekturdenkmal von nationaler Bedeutung, auch wenn es derzeit Restaurierungsbedarf aufweist. Der Park ist ein herausragendes Beispiel für die europäische Landschaftsarchitektur des frühen 20. Jahrhunderts in Osteuropa.",
      hu: "A Țaul-park Moldova északi részén található, és az ország legnagyobb és egyik legszebb dendrológiai parkjaként tartják számon. A 46 hektáron elterülő tájparkot a 20. század elején alakították ki az orosz bankár, Andrej Pommer kúriája körül, ötvözve a természetes lankákat a tudatosan tervezett növényvilággal. A park gyűjteménye lenyűgöző: több mint 150 különböző fa- és cserjefaj található itt, amelyek közül sok egzotikus tájakról, például Szibériából vagy Távol-Keletről származik. A park két részre oszlik: egy felső részre, ahol a kastély és a virágoskertek kaptak helyet, valamint egy alsóbb, erdősebb részre, amely tavakkal és kanyargós sétányokkal várja a látogatókat. A Pommer-kúria eklektikus épülete a park központi eleme, amely bár felújításra szorul, ma is hirdeti a régió egykori arisztokratikus pompáját.",
      ro: "Parcul Țaul din raionul Dondușeni este cel mai mare parc din Republica Moldova, având o suprafață de 46 de hectare. Acesta a fost amenajat între anii 1901 și 1912 în jurul conacului bancherului Andrei Pommer. Proiectul a fost realizat de arhitectul peisagist Ippolit Padalko, care a creat o armonie perfectă între flora locală și specii exotice. Parcul este structurat într-o zonă superioară, unde se află conacul, și o zonă inferioară cu aspect forestier. Cuprinde peste 150 de specii de arbori și arbuști, mulți dintre aceștia fiind aduși din diverse colțuri ale lumii. Conacul în sine este un monument de arhitectură de importanță națională, fiind un exemplu remarcabil de arhitectură peisagistică europeană de la începutul secolului XX în Europa de Est.",
      en: "Taul Park in the Dondușeni District is the largest park in the Republic of Moldova, spanning 46 hectares. it was created between 1901 and 1912 around the manor house of the banker Andrei Pommer. The landscape design was executed by Ippolit Padalko, who achieved a harmonious blend of native and exotic plants. The park is divided into an upper section containing the manor and a lower section with a more forested character. It features over 150 species of trees and shrubs, many of which were imported from various parts of the world. The manor house itself is an architectural monument of national importance, representing a prime example of early 20th-century European landscape architecture in Eastern Europe.",
      es: "El parque de Taul es el parque paisajístico más grande de Moldavia y rodea el histórico castillo de Pommer. Reúne más de 150 especies de árboles y arbustos en un jardín de estilo inglés.",
      pt: "O parque de Taul é o maior parque paisagístico da Moldávia e rodeia o histórico castelo de Pommer. Reúne mais de 150 espécies de árvores e arbustos num jardim de estilo inglês.",
      fr: "Le parc de Taul est le plus grand parc paysager de Moldavie et entoure le château historique de Pommer. Il réunit plus de 150 espèces d'arbres et d'arbustes dans un jardin à l'anglaise.",
    },
