    image: "/poi-images/moldova-saharna-reserve-life-v2.webp",
    coords: [28.9667, 47.7011],
    coords: [28.9667, 47.7011],
    description: {
      de: "Saharna ist berühmt für seine tiefen Schluchten, Wasserfälle und die reiche Artenvielfalt in den Kalksteinfelsen entlang des Dnister. Die Region kombiniert natürliche Schönheit mit spiritueller Bedeutung.",
      hu: "Saharna híres mély szurdokairól, vízeséseiről és a Dnyeszter menti mészkősziklák gazdag élővilágáról. A régió egyesíti a természeti szépséget a spirituális jelentőséggel.",
      ro: "Saharna este celebră pentru defileurile adânci, cascadele sale și biodiversitatea bogată din stâncile de calcar de-a lungul Nistrului. Regiunea îmbină frumusețea naturală cu cea spirituală.",
      en: "Saharna is famous for its deep gorges, waterfalls, and rich biodiversity within the limestone cliffs along the Dniester. The region combines natural beauty with spiritual significance.",
      es: "Saharna es famosa por sus profundos desfiladeros, cascadas y la rica biodiversidad en los acantilados de piedra caliza a lo largo del Dniéster. La región combina belleza natural con significado espiritual.",
      pt: "Saharna é famosa pelos seus profundos desfiladeiros, cascatas e a rica biodiversidade nas falésias de calcário ao longo do Dniestre. A região combina beleza natural com significado espiritual.",
      fr: "Saharna est célèbre pour ses canyons profonds, ses cascades et sa riche biodiversité dans les falaises calcaires le long du Dniestr. La région allie beauté naturelle et importance spirituelle.",
    },
    facts: {
      de: ["Bekannt für 22 Wasserfälle", "Höchster Wasserfall ist 10m", "Relikte aus der Eiszeit", "Beliebtes Wandergebiet"],
      hu: ["22 vízeséséről ismert", "A legmagasabb vízesés 10 méter", "Jégkorszaki reliktumok", "Népszerű túraútvonal"],
      ro: ["Cunoscută pentru cele 22 cascade", "Cea mai înaltă cascadă are 10m", "Plante relicte glaciare", "Zonă populară de drumeții"],
      en: ["Known for 22 waterfalls", "Highest waterfall is 10m high", "Glacial relict plants", "Popular hiking destination"],
      es: ["Conocida por sus 22 cascadas", "La cascada más alta mide 10 m", "Reliquias de la Edad de Hielo", "Popular zona de senderismo"],
      pt: ["Conhecida pelas suas 22 cascatas", "A cascata mais alta tem 10 m", "Relíquias da Idade do Gelo", "Popular área de caminhadas"],
      fr: ["Connue pour ses 22 cascades", "La plus haute cascade mesure 10 m", "Reliques de l'âge de glace", "Zone de randonnée populaire"],
    },
    imageHint: "Saharna waterfalls and cliffs Moldova",
    image: "/poi-images/moldova-saharna-reserve-life-v2.webp",
    descriptionAdvanced: {
      de: "Das Landschaftsreservat Saharna erstreckt sich über 670 Hektar im Bezirk Rezina am rechten Ufer des Dnjestr. Es ist bekannt für seine spektakuläre Schlucht, die der Fluss Saharna in das Kalksteinplateau gegraben hat. In der Schlucht befinden sich 22 Wasserfälle, von denen 'Gipsy Hole' mit 10 Metern Fallhöhe der bekannteste ist. Das Reservat beherbergt das Kloster Saharna aus dem 18. Jahrhundert, eines der bedeutendsten orthodoxen Pilgerzentren Moldaus. Archäologische Ausgrabungen haben zudem eine Geto-Dakische Festung und Felsenklöster aus dem 13. Jahrhundert freigelegt. Die Flora umfasst seltene Felspflanzen, während die Fauna durch Greifvögel geprägt ist, die in den steilen Felswänden nisten. Die Kombination aus Naturwundern und historischem Erbe macht Saharna zu einem einzigartigen Ort.",
      hu: "Saharna Moldova egyik leglátványosabb természetvédelmi területe, ahol a Dnyeszter menti mészkősziklák drámai mélységű szurdokokat alkotnak. A terület központja a Saharna-patak völgye, amely összesen 22 kisebb-nagyobb vízesést rejt, köztük a leghíresebb a 10 méter magas Gropile-vízesés. A szurdokvölgy mikroklímája különleges, hiszen számos olyan jégkorszaki maradványnövényt őriz meg, amelyek máshol már eltűntek a régióból a felmelegedés miatt. A természeti értékek szorosan összefonódnak a spirituális élettel: a sziklákba vájt kolostor és a közelben található szent források miatt a hely fontos zarándokközpont is a helyiek számára. A túrázók számára a meredek ösvények lélegzetelállító kilátást nyújtanak a kanyargó folyóra és a környező erdőségekre, miközben feltárulnak a vaskori erődítmények és géta-dák települések régészeti nyomai is, tanúskodva a táj ősi lakottságáról.",
      ro: "Rezervația peisagistică Saharna se întinde pe o suprafață de 670 de hectare în raionul Rezina, pe malul drept al Nistrului. Este renumită pentru defileul spectaculos săpat de râul Saharna în platoul calcaros. În cadrul defileului se găsesc 22 de cascade, cea mai cunoscută fiind 'Groapa Țiganului', cu o înălțime de 10 metri. Rezervația adăpostește Mănăstirea Saharna, fondată în secolul al XVIII-lea, unul dintre cele mai importante centre de pelerinaj ortodox din Moldova. Săpăturile arheologice au scos la iveală o cetate geto-dacică și lăcașuri rupestre datând din secolul al XIII-lea. Flora include plante saxicole rare, iar fauna este reprezentată de păsări răpitoare care cuibăresc pe pereții abrupți. Combinația dintre monumentele naturii și patrimoniul istoric conferă locului un caracter unic.",
      en: "The Saharna Landscape Reserve covers 670 hectares in the Rezina District on the right bank of the Dniester River. It is renowned for its spectacular canyon carved by the Saharna River into the limestone plateau. Within the canyon, there are 22 waterfalls, the most famous being 'Gipsy Hole' with a height of 10 meters. The reserve is home to the 18th-century Saharna Monastery, one of Moldova's most significant Orthodox pilgrimage sites. Archaeological excavations have also uncovered a Geto-Dacian fortress and rock monasteries dating back to the 13th century. The flora includes rare rock-dwelling plants, while the fauna is characterized by birds of prey nesting in the steep cliffs. The combination of natural wonders and historical heritage makes Saharna a unique destination.",
      es: "La reserva de Saharna es célebre por sus profundos cañones, 22 cascadas y su monasterio rupestre. Los acantilados de piedra caliza ofrecen vistas espectaculares de la orilla del río Dniéster.",
      pt: "A reserva de Saharna é célebre pelos seus profundos desfiladeiros, 22 cascatas e o seu mosteiro rupestre. As falésias de calcário oferecem vistas espetaculares sobre a margem do rio Dniestre.",
      fr: "La réserve de Saharna est célèbre pour ses gorges profondes, ses 22 cascades et son monastère rupestre. Les falaises calcaires offrent des vues spectaculaires sur les rives du Dniestr.",
    },
