    imageHint: "Tipova cliffs overlooking Dniester river",
    image: "/poi-images/moldova-tipova-reserve-life-v2.webp",
    descriptionAdvanced: {
      de: "Das Landschaftsreservat Tipova liegt im Bezirk Rezina am Ufer des Dnjestr und umfasst etwa 306 Hektar. Es ist vor allem für sein Felsenkloster bekannt, das eines der größten und ältesten seiner Art in Südosteuropa ist. Die Klosteranlage besteht aus drei Komplexen, die zwischen dem 11. und 15. Jahrhundert in die weichen Kalksteinfelsen gehauen wurden. Das Reservat beeindruckt durch seine tiefen Schluchten und Wasserfälle, die der Fluss Tipova auf seinem Weg zum Dnjestr bildet. Die Legende besagt, dass hier der moldauische Fürst Stefan der Große seine Frau Maria Voichița heiratete und dass der mythologische Dichter Orpheus hier seine letzte Ruhe fand. Die ökologische Vielfalt umfasst zahlreiche bedrohte Pflanzenarten der Steppen- und Waldzone.",
      hu: "A Tipova tájvédelmi körzet a Rezina járásban, a Dnyeszter partján található, és mintegy 306 hektárt foglal el. Elsősorban sziklakolostoráról ismert, amely Délkelet-Európa egyik legnagyobb és legrégebbi ilyen típusú létesítménye. A kolostoregyüttes három részből áll, amelyeket a 11. és 15. század között vájtak a puha mészkősziklákba. A rezervátum mély szurdokaival és vízeséseivel nyűgöz le, amelyeket a Tipova folyó alkot a Dnyeszter felé vezető útján. A legenda szerint itt vette feleségül III. István moldovai fejedelem Maria Voichițát, és a mitológiai költő, Orpheusz is itt lelt végső nyugalomra. Az ökológiai sokféleség a sztyeppei és erdei zónák számos veszélyeztetett növényfaját foglalja magában.",
      ro: "Rezervația peisagistică Țipova este situată în raionul Rezina, pe malul Nistrului, acoperind o suprafață de aproximativ 306 hectare. Este celebră în special pentru mănăstirea sa rupestră, una dintre cele mai mari și mai vechi de acest tip din Europa de Sud-Est. Complexul monastic cuprinde trei ansambluri sculptate în stânca de calcar moale între secolele XI și XV. Rezervația impresionează prin defileurile sale adânci și cascadele formate de râul Țipova în drumul său spre Nistru. Legenda spune că aici domnitorul Ștefan cel Mare s-ar fi cununat cu Maria Voichița și că poetul mitologic Orfeu și-ar fi găsit sfârșitul în aceste locuri. Diversitatea ecologică include numeroase specii de plante periclitate specifice zonelor de stepă și silvostepă.",
      en: "The Tipova Landscape Reserve is located in the Rezina District on the banks of the Dniester River, covering about 306 hectares. It is primarily famous for its rock monastery, which is one of the largest and oldest of its kind in Southeastern Europe. The monastic complex consists of three sections carved into the soft limestone cliffs between the 11th and 15th centuries. The reserve impresses with its deep ravines and waterfalls formed by the Tipova River on its way to the Dniester. Legend has it that the Moldovan Prince Stephen the Great married Maria Voichița here and that the mythological poet Orpheus found his final resting place in these lands. The ecological diversity includes numerous endangered plant species characteristic of steppe and forest-steppe zones.",
      es: "Tipova es uno de los mayores conjuntos de monasterios rupestres de Europa del Este, enclavado en una reserva paisajística. Impresiona por sus escarpados acantilados y cascadas en forma de terraza.",
      pt: "Tipova é um dos maiores conjuntos de mosteiros rupestres da Europa de Leste, situado numa reserva paisagística. Impressiona pelas suas falésias íngremes e cascatas em forma de terraço.",
      fr: "Tipova est l'un des plus grands ensembles de monastères rupestres d'Europe de l'Est, niché dans une réserve paysagère. Il impressionne par ses falaises abruptes et ses cascades en terrasses.",
    },
    factsAdvanced: {
      de: ["Fläche: 306 Hektar", "Größtes Felsenkloster Moldaus", "Klosterkomplexe stammen aus dem 11.-15. Jahrhundert", "Beinhaltet 18 separate Felsenzellen", "Wasserfälle mit bis zu 16 Metern Fallhöhe", "Befindet sich nahe der Ortschaft Tipova"],
      hu: ["Terület: 306 hektár", "Moldova legnagyobb sziklakolostora", "A kolostoregyüttes a 11-15. századból származik", "18 különálló sziklacellát tartalmaz", "Akár 16 méter magas vízesések", "Tipova település közelében található"],
      ro: ["Suprafața: 306 hectare", "Cea mai mare mănăstire rupestră din Moldova", "Ansamblurile monastice datează din sec. XI-XV", "Include 18 chilii rupestre separate", "Cascade cu înălțimi de până la 16 metri", "Situată în apropierea satului Țipova"],
      en: ["Area: 306 hectares", "Largest rock monastery in Moldova", "Monastic complexes date from 11th-15th centuries", "Contains 18 separate rock cells", "Waterfalls with drops of up to 16 meters", "Located near the village of Tipova"],
      es: ["306 hectáreas de superficie protegida", "Contiene más de 18 cámaras rupestres", "La cascada más alta alcanza los 16 metros", "El monasterio data en parte del siglo XI"],
      pt: ["306 hectares de área protegida", "Contém mais de 18 câmaras rupestres", "A cascata mais alta atinge os 16 metros", "O mosteiro data em parte do século XI"],
      fr: ["Surface protégée de 306 hectares", "Contient plus de 18 chambres rupestres", "La plus haute cascade atteint 16 mètres", "Le monastère date en partie du XIe siècle"],
    },
