      pt: "Naslavcea, no ponto mais setentrional da Moldávia, é conhecida pelos seus afloramentos geológicos e rica flora na curva do Dniester. A área é famosa por achados fósseis e tufo vulcânico.",
      fr: "Naslavcea, au point le plus au nord de la Moldavie, est connue pour ses affleurements géologiques et sa flore riche dans le méandre du Dniestr. La région est célèbre pour ses découvertes de fossiles et son tuf volcanique.",
