      de: "Der Beleu-See ist ein Reliktsee im Pruth-Tal und das Herzstück des Reservats Prutul de Jos. Er ist bekannt für seine schwimmenden Inseln und als Paradies für Wasservögel.",
      hu: "A Beleu-tó egy reliktumtó a Prut völgyében, az Alsó-Prut rezervátum szíve. Híres úszó szigeteiről és a vízimadarak paradicsomaként ismerik.",
      ro: "Lacul Beleu este un lac relict în valea Prutului și inima rezervației Prutul de Jos. Este cunoscut pentru insulele sale plutitoare și ca paradis pentru păsările acvatice.",
      en: "Beleu Lake is a relict lake in the Prut valley and the heart of the Lower Prut Reserve. It is known for its floating islands and as a paradise for water birds.",
