    name: { de: "Rudi-Arionești Reservat", hu: "Rudi-Arionești Tájvédelmi Körzet", ro: "Rezervația Rudi-Arionești", en: "Rudi-Arionesti Reserve"},
    image: "/poi-images/moldova-rudi-arionesti-life-v2.webp",
