      hu: "Cosăuți a Dnyeszter menti geológiai képződményeiről, különösen a gránitkibúvásokról ismert. A rezervátum értékes erdei és folyóparti ökoszisztémákat véd.",
      ro: "Cosăuți este cunoscută pentru formațiunile geologice de-a lungul Nistrului, în special aflorimentele de granit. Rezervația protejează ecosisteme forestiere și riverane valoroase.",
