      en: ["The reserve spans a total area of 435 hectares.", "It features the only granite outcrops found anywhere in Moldova.", "The Paleolithic site at Cosăuți dates back roughly 20,000 years.", "Cosăuți Monastery was originally established in the year 1729.", "The famous 'Soroca stone' is extracted from local quarries here.", "There is a sulfur spring within the reserve believed to have healing properties."],
      es: ["La superficie abarca unas 585 hectáreas", "Único lugar con granito en Moldavia", "Incluye huellas de asentamientos paleolíticos", "Conocida por las cruces de piedra tradicionales"],
