      pt: "O Dendrarium de Chișinău é um oásis verde com uma vasta coleção de plantas lenhosas. Serve para a conservação de espécies de árvores raras e oferece um refúgio tranquilo na cidade.",
      fr: "Le Dendrarium de Chișinău est une oasis de verdure abritant une vaste collection de plantes ligneuses. Il sert à la conservation d'espèces d'arbres rares et offre un refuge paisible en ville.",
